import{z as p,x as B,o as r,c,q as n,j as s,D as t,d as e,s as E,S as i,b as l}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"混合逻辑时钟 HLC","description":"","frontmatter":{"title":"混合逻辑时钟 HLC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hlc.md","filePath":"cs/hlc.md","lastUpdated":1791063341000}'),d={name:"cs/hlc.md"};function m(A,a,C,h,L,u){const o=B("Mermaid");return r(),c("div",null,[a[2]||(a[2]=n('<h1 id="混合逻辑时钟-hlc" tabindex="-1">混合逻辑时钟 HLC <a class="header-anchor" href="#混合逻辑时钟-hlc" aria-label="Permalink to &quot;混合逻辑时钟 HLC&quot;">​</a></h1><div class="epigraph"><p>HLC 把 NTP 可读的物理时间与 Lamport 计数焊在一处：既大致可按墙钟排序，又在误差里保住 happened-before。</p><footer>—— 据 Kulkarni, Demirbas, Madappa, Avva and Leone, Logical Physical Clocks, OPODIS 2014 整理</footer></div><p>上一课<a href="/cs/vector-clocks">向量时钟</a>给了完备因果，但 \\(O(n)\\) 太大，且时间戳不能当「几点几分」给运维看。缺口是<strong>单整数（或短元组）上的因果，同时贴近物理时间</strong>。本课不重证 \\(V(a)\\lt V(b)\\Leftrightarrow a\\to b\\)。后课快照仍用 Chandy–Lamport 的标记，不把 HLC 当全局割。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Lamport 标量钟的数字会与墙钟脱节：长时间只本地事件，逻辑时间猛涨，或反过来墙钟超前很多。运维、调试、粗粒度 TTL 想读物理时间；协议想要 \\(a\\to b\\Rightarrow T(a)\\lt T(b)\\)。缺口不是再做一个 NTP，而是 <strong>pt + 逻辑计数</strong>：在时钟误差范围内跟着墙走，误差撑不住时用计数把因果顶住。</p><p>Kulkarni 等人的 HLC：每个事件一个 \\((l,c)\\)。\\(l\\) 跟踪 \\(\\max(\\text{本地物理}, \\text{收到的 }l)\\)；\\(c\\) 在 \\(l\\) 不变时当 Lamport 计数。比较先看 \\(l\\) 再看 \\(c\\)。这样 \\(a\\to b\\Rightarrow (l,c)_a\\lt (l,c)_b\\)，并且 \\(l\\) 通常靠近 NTP。</p><p><span class="marginnote">HLC 不是 TrueTime：它不暴露 \\(\\varepsilon\\)，也不提供外部一致性。它只是更好打印、更好做粗排序的逻辑钟。</span></p><p><span class="marginnote">直觉类比：HLC 像「手表加排队号」——手表（\\(l\\)）尽量跟着标准时间走，同一毫秒里挤进多个事件就发排队号（\\(c\\)）：09:00:00.123#0、#1、#2。看时间戳既知道大概几点，也能比出先后。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>发送、接收、本地事件都更新 \\((l,c)\\)：新 \\(l\\) 取本地物理与消息 \\(l\\) 的最大；若 \\(l\\) 前进则 \\(c\\) 清零，否则 \\(c\\) 加一。溢出时必须把 \\(l\\) 往前推或拒绝——实现要定策略。存储时往往打包成 64 位：高位物理毫秒，低位计数。</p>',10)),(r(),s(i,null,{default:t(()=>[E(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PT%5B%22%E7%89%A9%E7%90%86%E9%92%9F%22%5D%20--%3E%20L%5B%22l%20%E5%88%86%E9%87%8F%22%5D%0A%20%20MSG%5B%22%E6%B6%88%E6%81%AF%E4%B8%AD%E7%9A%84%20l%2Cc%22%5D%20--%3E%20L%0A%20%20L%20--%3E%20C%5B%22c%3A%20l%20%E4%B8%8D%E5%8F%98%E5%88%99%E5%8A%A0%E4%B8%80%22%5D%0A%20%20C%20--%3E%20ORD%5B%22%E5%AD%97%E5%85%B8%E5%BA%8F%20%E2%89%88%20%E5%9B%A0%E6%9E%9C%E5%85%A8%E5%BA%8F%E6%89%A9%E5%B1%95%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("p",null,[e("与向量钟：HLC 仍只是全序扩展，"),l("strong",null,"不能"),e("判定并发。要并发检测继续用版本向量。HLC 解决的是「一个时间戳既可读又尊重因果」。")],-1)),a[4]||(a[4]=l("p",null,[l("span",{class:"marginnote"},"数字实例：打包成 64 位时，常取高 48 位放毫秒（够记约 8900 年）、低 16 位放计数。同一毫秒最多挤 65536 个事件，再多就得把 \\(l\\) 往前推——「溢出策略必须实现里定好」说的就是这一天。")],-1)),a[5]||(a[5]=l("h2",{id:"机制",tabindex:"-1"},[e("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=l("p",null,"若物理钟回拨，HLC 的 \\(l\\) 不减（取 max），表现为逻辑领先物理，直到墙钟追上。这比直接写墙钟安全：不会让因果后继的时间戳变小。对时超前后，\\(l\\) 跟着走，\\(c\\) 经常为零，日志看起来像普通毫秒时间戳。",-1)),a[7]||(a[7]=l("p",null,"收到消息时 \\((l,c)\\) 怎么更新，分三种情形：",-1)),(r(),s(i,null,{default:t(()=>[E(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E6%94%B6%E5%88%B0%E6%B6%88%E6%81%AF%E6%90%BA%E5%B8%A6%20(lm%2C%20cm)%22%5D%20--%3E%20C%7B%22lm%20%E4%B8%8E%E6%9C%AC%E5%9C%B0%20l%20%E6%AF%94%E8%BE%83%22%7D%0A%20%20C%20--%20%22lm%20%E6%9B%B4%E5%A4%A7%22%20--%3E%20U1%5B%22l%20%E5%8F%96%20lm%2C%20c%20%E6%B8%85%E9%9B%B6%22%5D%0A%20%20C%20--%20%22lm%20%E7%9B%B8%E7%AD%89%22%20--%3E%20U2%5B%22l%20%E4%B8%8D%E5%8F%98%2C%20c%20%E5%8F%96%20max(c%2C%20cm)%20%2B%201%22%5D%0A%20%20C%20--%20%22lm%20%E6%9B%B4%E5%B0%8F%22%20--%3E%20U3%5B%22l%20%E4%B8%8D%E5%8F%98%2C%20c%20%E5%8A%A0%E4%B8%80%22%5D%0A%20%20U1%20--%3E%20D%5B%22%E5%BE%97%E5%88%B0%E5%8F%AF%E6%AF%94%E8%BE%83%E7%9A%84%E4%BA%8B%E4%BB%B6%E6%97%B6%E9%97%B4%E6%88%B3%22%5D%0A%20%20U2%20--%3E%20D%0A%20%20U3%20--%3E%20D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=n('<p><span class="marginnote">常见误区：以为「HLC 时间戳大」就能断定「无并发」。两个并发写完全可能拿到相同甚至颠倒直觉的 \\((l,c)\\)——HLC 只保证因果后继的时间戳严格更大，反推不出因果；判并发仍要用版本向量。</span></p><p>CockroachDB 一类系统用 HLC 给事务时间戳，再在误差窗口上做不确定性处理——细节是数据库课与后课地理复制的交界，本课只准备时间戳形状。不要把 HLC 写成 Spanner TrueTime 的平替：没有 API 级 \\(\\varepsilon\\)，就不能 commit wait。</p><p>本课不把混合钟推广成「可以替代向量」：维数压缩与因果完备是两回事。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Hybrid Vector Clock 全文，不证相对 NTP 的误差公式。不引入区块链出块时间。后课默认：需要打印与粗排序用 HLC；需要检测并发写用向量；需要全局一致割用快照算法，不是比较 HLC。</p><p>物理钟误差仍在：\\(l\\) 贴近墙钟不等于跨机 \\(|Δl|\\) 大于 \\(2\\varepsilon\\)。因果保证来自计数规则，来自 NTP。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>HLC 是带物理跟踪的 Lamport 钟，不是向量钟。</li><li>\\(a\\to b\\) 蕴含时间戳增大；并发仍不可判定。</li><li>回拨时 \\(l\\) 不减，靠 \\(c\\) 顶住因果。</li><li>出处：Kulkarni et al., OPODIS 2014。</li></ul>',8))])}const b=p(d,[["render",m]]);export{T as __pageData,b as default};
